EOF#!/usr/bin/env python3
"""
pack_loader.py -- Build DrayBoot TFTP image for Vigor 2860.

Reads kernel constants from vmlinux-initramfs.elf, patches them into
stub.bin, then assembles the final TFTP file.

Usage:
    python3 pack_loader.py stub.bin vmlinux-initramfs.elf dtb.bin [out.bin]
    python3 pack_loader.py --verify out.bin
"""

import sys, struct, subprocess, os

# ── fixed constants (never change) ──────────────────────────────────────────
KERN_LOAD   = 0x80002000
TFTP_BASE   = 0x80800000
DRAY_HDR    = 0x8100
KERN_SRC    = TFTP_BASE + DRAY_HDR     # 0x80808100
RAM_END     = 0x80000000 + 0x8000000   # 0x88000000  (128 MB)

PAYLOAD_MAX = 0x7FFC
DRAY_TOTAL  = 0x8100
DRAY_SIG    = b'rDkmfaaryTedecz\x00'

# ── sentinel values in stub.bin (must match stub.S #defines) ────────────────
SENTINELS = {
    'KERN_ENTRY':  0xDEAD0001,
    'KERN_SRC_W':  0xDEAD0002,
    'DTB_SRC':     0xDEAD0003,
    'DTB_DST':     0xDEAD0004,
    'DTB_SIZE_W':  0xDEAD0005,
    'SYNCI_END':   0xDEAD0006,
}

CROSS = '/work/staging_dir/toolchain-mips_24kc_gcc-13.3.0_musl/bin/mips-openwrt-linux-musl-'

# ── helpers ──────────────────────────────────────────────────────────────────
def read_elf(elf_path):
    out = subprocess.check_output([f'{CROSS}readelf', '-h', '-l', '-s',
                                   '--wide', elf_path]).decode()
    entry, filesz, memsz = None, None, None
    for line in out.splitlines():
        if 'Entry point' in line:
            entry = int(line.split()[-1], 16)
        if 'FileSiz' in line and filesz is None:
            parts = line.split()
            filesz = int(parts[4], 16)
            memsz  = int(parts[5], 16)
    if None in (entry, filesz, memsz):
        raise RuntimeError(f"Could not parse ELF headers from {elf_path}")
    return entry, filesz, memsz

def read_appended_dtb(debug_elf):
    """Find __appended_dtb address from the debug ELF (has symbols)."""
    path = debug_elf.replace('.elf', '.debug')
    if not os.path.exists(path):
        raise FileNotFoundError(f"Debug ELF not found: {path}\n"
                                "Need it to locate __appended_dtb.")
    nm = subprocess.check_output(
        [f'{CROSS}nm', path]).decode()
    for line in nm.splitlines():
        if '__appended_dtb' in line:
            return int(line.split()[0], 16)
    raise RuntimeError("__appended_dtb symbol not found in debug ELF")

def patch_stub(stub: bytes, values: dict) -> bytes:
    """Replace each sentinel word (big-endian) with its real value."""
    ba = bytearray(stub)
    for name, sentinel in SENTINELS.items():
        packed_sentinel = struct.pack('>I', sentinel)
        idx = ba.find(packed_sentinel)
        if idx == -1:
            raise RuntimeError(f"Sentinel {name}={sentinel:#010x} not found in stub")
        struct.pack_into('>I', ba, idx, values[name])
        print(f"  Patched {name:12s} @ offset {idx:#06x} = {values[name]:#010x}")
    return bytes(ba)

def drayboot_checksum(data: bytes) -> int:
    total = 0
    for i in range(DRAY_TOTAL // 4 - 1):
        (w,) = struct.unpack_from('>I', data, i * 4)
        total = (total + w) & 0xFFFFFFFF
    return (~total) & 0xFFFFFFFF

def build_drayboot_image(stub_patched: bytes) -> bytes:
    if len(stub_patched) > PAYLOAD_MAX:
        raise ValueError(f"Stub {len(stub_patched)} bytes > max {PAYLOAD_MAX}")
    img = bytearray(DRAY_TOTAL)
    struct.pack_into('>I', img, 0x00, DRAY_TOTAL)
    img[0x08:0x08+len(DRAY_SIG)] = DRAY_SIG
    img[0x100:0x100+len(stub_patched)] = stub_patched
    csum = drayboot_checksum(bytes(img))
    struct.pack_into('>I', img, 0x80FC, csum)
    return bytes(img)

# ── main ─────────────────────────────────────────────────────────────────────
def main():
    if len(sys.argv) == 3 and sys.argv[1] == '--verify':
        verify(sys.argv[2]); return

    if len(sys.argv) not in (4, 5):
        print("Usage: pack_loader.py stub.bin vmlinux-initramfs.elf dtb.bin [out.bin]")
        sys.exit(1)

    stub_f = sys.argv[1]
    elf_f  = sys.argv[2]
    dtb_f  = sys.argv[3]
    out_f  = sys.argv[4] if len(sys.argv) == 5 else 'vigor2860_loader.bin'

    with open(stub_f, 'rb') as f: stub = f.read()
    with open(dtb_f,  'rb') as f: dtb  = f.read()

    # pad DTB to word boundary
    if len(dtb) % 4:
        dtb += b'\x00' * (4 - len(dtb) % 4)

    print(f"Reading ELF: {elf_f}")
    entry, filesz, memsz = read_elf(elf_f)
    dtb_dst = read_appended_dtb(elf_f)

    dtb_src   = KERN_SRC + filesz
    synci_end = dtb_dst  + len(dtb)

    values = {
        'KERN_ENTRY': entry,
        'KERN_SRC_W': filesz // 4,
        'DTB_SRC':    dtb_src,
        'DTB_DST':    dtb_dst,
        'DTB_SIZE_W': len(dtb) // 4,
        'SYNCI_END':  synci_end,
    }

    print(f"\nKernel:  entry={entry:#010x}  filesz={filesz:#010x}  memsz={memsz:#010x}")
    print(f"DTB:     dst={dtb_dst:#010x}  src={dtb_src:#010x}  size={len(dtb):#x}")
    print(f"\nPatching stub:")
    stub_patched = patch_stub(stub, values)

    print(f"\nBuilding DrayBoot image...")
    dray_img = build_drayboot_image(stub_patched)
    csum = struct.unpack_from('>I', dray_img, 0x80FC)[0]
    print(f"  Checksum: {csum:#010x}")

    total = len(dray_img) + filesz + len(dtb)
    if TFTP_BASE + total >= RAM_END:
        print("ERROR: TFTP image overflows 128 MB RAM"); sys.exit(1)

    print(f"\nRuntime map:")
    print(f"  TFTP base:   {TFTP_BASE:#010x}")
    print(f"  Kernel src:  {KERN_SRC:#010x}  ->  dst: {KERN_LOAD:#010x}")
    print(f"  DTB src:     {dtb_src:#010x}  ->  dst: {dtb_dst:#010x}")
    print(f"  Entry:       {entry:#010x}")
    print(f"  TFTP end:    {TFTP_BASE + total:#010x}  (RAM end: {RAM_END:#010x})")

    with open(out_f, 'wb') as f:
        f.write(dray_img)
        # write raw kernel binary (not the .elf -- the raw binary)
        kern_bin = elf_f.replace('.elf', '')
        if not os.path.exists(kern_bin):
            kern_bin = elf_f.replace('.elf','') 
            raise FileNotFoundError(
                f"Raw kernel binary not found at {kern_bin}\n"
                f"Pass path to vmlinux-initramfs (not the .elf)")
        with open(kern_bin, 'rb') as kf:
            f.write(kf.read())
        f.write(dtb)

    print(f"\nWrote: {out_f}  ({total/1024/1024:.1f} MB)")

def verify(path):
    with open(path, 'rb') as f: data = f.read()
    hdr = data[:DRAY_TOTAL]
    length  = struct.unpack_from('>I', hdr, 0x00)[0]
    sig     = hdr[0x08:0x17]
    stored  = struct.unpack_from('>I', hdr, 0x80FC)[0]
    computed = drayboot_checksum(bytes(hdr))
    print(f"Length:    {length:#010x}  (expect 0x00008100)")
    print(f"Signature: {sig}")
    print(f"Checksum:  {stored:#010x}  computed={computed:#010x}  "
          f"{'OK' if stored==computed else 'MISMATCH'}")
    # check for sentinel leftovers
    for name, s in SENTINELS.items():
        if struct.pack('>I', s) in hdr:
            print(f"WARNING: sentinel {name} ({s:#010x}) still present -- not patched!")
    kern_off = DRAY_TOTAL
    elf_magic = struct.unpack_from('>I', data, kern_off)[0]
    print(f"Kernel @{kern_off:#x}: first word = {elf_magic:#010x}")
    dtb_off = DRAY_TOTAL   # we don't know exact filesz here, just flag
    print("Run with full args to see DTB magic check.")

if __name__ == '__main__':
    main()
