KERN_LOAD   = 0x80002000
TFTP_BASE   = 0x80800000
DRAY_HDR    = 0x8100
KERN_SRC    = TFTP_BASE + DRAY_HDR     # 0x80808100
RAM_END     = 0x80000000 + 0x8000000   # 0x88000000  (128 MB)

PAYLOAD_MAX = 0x7FFC
DRAY_TOTAL  = 0x8100
DRAY_SIG    = b'rDkmfaaryTedecz\x00'

