    """Find __appended_dtb address from the debug ELF (has symbols)."""
    path = debug_elf.replace('.elf', '.debug')
    if not os.path.exists(path):
        raise FileNotFoundError(f"Debug ELF not found: {path}\n"
                                "Need it to locate __appended_dtb.")
    nm = subprocess.check_output(
        [f'{CROSS}nm', path]).decode()
    for line in nm.splitlines():
        if '__appended_dtb' in line:
            return int(line.split()[0], 16)
    raise RuntimeError("__appended_dtb symbol not found in debug ELF")

