    values = {
        'KERN_ENTRY': entry,
        'KERN_SRC_W': filesz // 4,
        'DTB_SRC':    dtb_src,
        'DTB_DST':    dtb_dst,
        'DTB_SIZE_W': len(dtb) // 4,
        'SYNCI_END':  synci_end,
    }

