    struct.pack_into('>I', img, 0x00, DRAY_TOTAL)
    img[0x08:0x08+len(DRAY_SIG)] = DRAY_SIG
    img[0x100:0x100+len(stub_patched)] = stub_patched
    csum = drayboot_checksum(bytes(img))
    struct.pack_into('>I', img, 0x80FC, csum)
    return bytes(img)

